/** [keys] (D14) name bodies for correspondence; null corresponds by order and geometry. */ @Immutable data class ShapeTarget(val bodies: List<RoundRect>,val join: JoinPolicy=JoinPolicy.ConcaveFillet,val strain: GlassStrain=GlassStrain.None,val keys: List<Any>?=null)
enum class JoinPolicy { ConcaveFillet,Union }; @Immutable data class GlassStrain(val strain: Float,val depth: Float) { companion object { val None=GlassStrain(0f,0f) } }; @Stable interface ShapeView { val key: Any; fun outline(): ShapeFrame; fun outlineAt(stamp: FrameStamp): ShapeFrame }
/** One published frame. [path] is the GlassSilhouette Union fold over nonzero-area bodies, or with [join] the #556 ConcaveFillet contour; built once on first read and never reset. */ @Immutable class ShapeFrame internal constructor(val bodies: List<RoundRect>,val bounds: Rect,val cornerRadius: Float,val strain: GlassStrain,internal val join: JoinData?=null) { val path: Path by lazy { if(join!=null) filletInputs(bodies,join).let { (o,local,s) -> Path().apply { addPath(concaveFilletPath(local,join.gap,s),o) } } else bodies.filter { it.width>0 && it.height>0 }.fold(Path()) { c,b -> Path.combine(PathOperation.Union,c,Path().apply { addRoundRect(b) }) } } }
/** D14: Engine-internal ConcaveFillet data, set by the U09 group adapter (Stage 4) and by nobody in Stage 3; [strength] indexes [ShapeFrame.bodies]. */ internal data class JoinData(val gap: Float,val rest: List<Rect>,val strength: (Int,Int)->Float)
/** D15: the solver input HoverPathCache builds: nonzero bodies on a 1/64 px grid from the first, one circular radius each (the smallest, fitted to the half side), pair strengths with the far-pair cutoff. */ internal fun filletInputs(bodies: List<RoundRect>,join: JoinData): Triple<Offset,List<RoundRect>,(Int,Int)->Float> { val solid=bodies.indices.filter { bodies[it].width>0 && bodies[it].height>0 }; val o=solid.firstOrNull()?.let { Offset(bodies[it].left,bodies[it].top) }?:Offset.Zero; val g={ v: Float -> round(v*64f)/64f }
    val local=solid.map { val b=bodies[it]; val l=g(b.left-o.x); val t=g(b.top-o.y); val r=g(b.right-o.x); val d=g(b.bottom-o.y); RoundRect(l,t,r,d,CornerRadius(minOf(listOf(b.topLeftCornerRadius,b.topRightCornerRadius,b.bottomRightCornerRadius,b.bottomLeftCornerRadius).minOf { min(it.x,it.y) },(r-l)/2f,(d-t)/2f).coerceAtLeast(0f))) }; return Triple(o,local) { a,b -> val i=min(a,b); val j=max(a,b); filletStrength(local[i].boundingRect,local[j].boundingRect,join.gap,join.strength(solid[i],solid[j])) } }
private val chartBounds=listOf(null,null,0.0..Double.POSITIVE_INFINITY,0.0..Double.POSITIVE_INFINITY)+List(8) { 0.0..1.0 } // Body chart (B1, 9:45 AM): left, top, width, height, then per side (top, right, bottom, left) the sum of its two radii as a fraction of the side and the clockwise-first corner's split of it. r_a+r_b ≤ side is Skia's own legal set, so every chart point is legal: no clamps.
private val sides=arrayOf(intArrayOf(0,2,0),intArrayOf(3,5,1),intArrayOf(4,6,0),intArrayOf(7,1,1)) // Per side: the radius indices (TL.x TL.y TR.x TR.y BR.x BR.y BL.x BL.y) of its clockwise corners and 0 for width, 1 for height.
internal fun bodyChart(b: RoundRect): FloatArray { val r=floatArrayOf(b.topLeftCornerRadius.x,b.topLeftCornerRadius.y,b.topRightCornerRadius.x,b.topRightCornerRadius.y,b.bottomRightCornerRadius.x,b.bottomRightCornerRadius.y,b.bottomLeftCornerRadius.x,b.bottomLeftCornerRadius.y); val wh=floatArrayOf(b.right-b.left,b.bottom-b.top)
    require((r+floatArrayOf(b.left,b.top)+wh).all { it.isFinite() } && wh.all { it>=0 } && r.all { it>=0 }) { "Shape bodies need finite ordered bounds and nonnegative radii" }; val s=sides.minOf { (a,c,d) -> val sum=r[a].toDouble()+r[c]; if(sum>wh[d]) wh[d]/sum else 1.0 }
    return floatArrayOf(b.left,b.top,wh[0],wh[1])+sides.flatMap { (a,c,d) -> val sum=(r[a].toDouble()+r[c])*s; listOf(if(wh[d]==0f) 0f else min(1.0,sum/wh[d]).toFloat(),if(sum==0.0) .5f else (r[a]*s/sum).toFloat()) } } // Skia's uniform scale once at admission, as addRoundRect draws it; a zero sum splits evenly.
private fun body(c: FloatArray,o: Int): RoundRect { val r=FloatArray(8); sides.forEachIndexed { k,(a,b,d) -> val sum=c[o+4+2*k]*c[o+2+d]; r[a]=sum*c[o+5+2*k]; r[b]=sum-r[a] }; return RoundRect(c[o],c[o+1],c[o]+c[o+2],c[o+1]+c[o+3],CornerRadius(r[0],r[1]),CornerRadius(r[2],r[3]),CornerRadius(r[4],r[5]),CornerRadius(r[6],r[7])) }; private fun centre(c: FloatArray,o: Int)=Offset(c[o]+c[o+2]/2,c[o+1]+c[o+3]/2)
private fun nearestEdge(p: Offset,c: FloatArray,o: Int): Offset { val l=c[o]; val t=c[o+1]; val r=l+c[o+2]; val b=t+c[o+3]; val q=Offset(p.x.coerceIn(l,r),p.y.coerceIn(t,b)); if(q!=p) return q; val d=floatArrayOf(p.x-l,r-p.x,p.y-t,b-p.y); return when(d.indices.minBy { d[it] }) { 0 -> Offset(l,p.y); 1 -> Offset(r,p.y); 2 -> Offset(p.x,t); else -> Offset(p.x,b) } }
private fun admit(t: ShapeTarget): Pair<ShapeTarget,List<FloatArray>> { val bodies=t.bodies.toList(); val keys=t.keys?.toList(); require(t.join==JoinPolicy.Union || bodies.all { b -> listOf(b.topLeftCornerRadius,b.topRightCornerRadius,b.bottomRightCornerRadius,b.bottomLeftCornerRadius).all { it.x==it.y && it==b.topLeftCornerRadius } }) { "ConcaveFillet bodies need one uniform circular corner radius" }; require(keys==null || keys.size==bodies.size && keys.toSet().size==keys.size) { "Body keys must be distinct, one per body" }; require(abs(t.strain.strain)<=StrainMotionSpan+StrainPressureSpan && abs(t.strain.depth)<=StrainDepthSpan) { "Strain outside its admitted span" }; return ShapeTarget(bodies,t.join,t.strain,keys) to bodies.map(::bodyChart) }
private class Slot(val id: Long,val channels: List<MotionFloat>,var key: Any?,var live: Boolean=true)
@Stable class PersistentShape internal constructor(private val clock: UiClock,initial: ShapeTarget,override val key: Any=Any()): ShapeView {
    private var nextId=0L; private var last: Any?=null; private var presented=false; private var rest: ShapeFrame?=null; private var moving: Pair<FrameStamp,ShapeFrame>?=null; private val epoch=mutableIntStateOf(0); private var lastStamp=clock.stampNow; internal var lastIntentWasRetarget=false; private set; private var join: JoinData?=null; private var policy=JoinPolicy.Union; private fun joined(t: ShapeTarget)=require(t.join==JoinPolicy.Union || t.bodies.isEmpty() || join!=null) { "ConcaveFillet bodies need JoinData first" }
    private val px=requireNotNull(clock.spec.geometry) { "Publish measured ExpansionGeometryDomain through U11.00 before creating a shape" }.maxViewportDiagonalPx; private var target: ShapeTarget; private var slots: List<Slot>; private val strain: List<MotionFloat>; private var flat: List<MotionFloat>
    init { val (t,charts)=admit(initial); joined(t); target=t; slots=charts.mapIndexed { j,c -> slot(c,t.keys?.get(j),lastStamp) }; strain=listOf(MotionFloat(clock,t.strain.strain,StrainMotionSpan+StrainPressureSpan,key=key to "strain"),MotionFloat(clock,t.strain.depth,StrainDepthSpan,key=key to "depth")); flat=strain+slots.flatMap { it.channels } }
    private fun slot(c: FloatArray,k: Any?,stamp: FrameStamp)=(++nextId).let { id -> Slot(id,List(12) { MotionFloat(clock,c[it],if(it<4) px else 1f,chartBounds[it],key to id to it,stamp) },k) }
    internal fun slotIds(live: Boolean=false)=slots.filter { !live || it.live }.map { it.id }; internal fun valuesAt(stamp: FrameStamp)=FloatArray(flat.size) { flat[it].rawValue(stamp).toFloat() }; internal fun velocitiesAt(stamp: FrameStamp)=FloatArray(flat.size) { flat[it].rawVelocity(stamp).toFloat() }
    private fun frame(stamp: FrameStamp): ShapeFrame { val v=valuesAt(stamp); val bodies=slots.indices.filter { slots[it].live || v[4+12*it]>0 && v[5+12*it]>0 }.map { body(v,2+12*it) }; val solid=bodies.filter { it.width>0 && it.height>0 }; return ShapeFrame(java.util.Collections.unmodifiableList(bodies),if(solid.isEmpty()) Rect.Zero else Rect(solid.minOf { it.left },solid.minOf { it.top },solid.maxOf { it.right },solid.maxOf { it.bottom }),bodies.firstOrNull()?.topLeftCornerRadius?.x?:0f,GlassStrain(v[0],v[1]),if(policy==JoinPolicy.ConcaveFillet) join else null) }
    private fun sampled(stamp: FrameStamp): ShapeFrame { if(!clock.isObserving) presented=true; if(stamp.nanos>=lastStamp.nanos && flat.all { it.kind==0 }) return rest?:frame(lastStamp).also { rest=it }; moving?.let { if(it.first===stamp) return it.second }; return frame(stamp).also { moving=stamp to it } }
    override fun outline(): ShapeFrame { epoch.intValue; var active=false; for(m in flat) { m.epoch.intValue; if(m.kind!=0) active=true }; return sampled(if(active) clock.stamp else lastStamp) }; override fun outlineAt(stamp: FrameStamp)=sampled(stamp)
    private fun changed(stamp: FrameStamp) { if(target.bodies.isNotEmpty()) policy=target.join; flat=strain+slots.flatMap { it.channels }; lastStamp=stamp; rest=null; moving=null; epoch.intValue++ }; private fun purge() { val gone=slots.filter { !it.live && it.channels.all { m -> m.kind==0 } }.toSet(); if(gone.isEmpty()) return; gone.forEach { s -> s.channels.forEach { it.dispose() } }; slots=slots-gone; changed(lastStamp) }
    private fun correspond(charts: List<FloatArray>,keys: List<Any>?,now: FloatArray): List<Pair<Slot?,Int?>> { // Order-preserving: match costs centre distance (keyed: 0 or never); a live slot dies at 1e12, a retiring slot drops free, a birth costs 1e9.
        val n=slots.size; val m=charts.size; val cost={ i: Int,j: Int -> if(keys!=null) (if(slots[i].key==keys[j]) 0.0 else Double.POSITIVE_INFINITY) else (centre(now,2+12*i)-centre(charts[j],0)).getDistance().toDouble() }; val skip={ i: Int -> if(slots[i].live) 1e12 else 0.0 }
        val d=Array(n+1) { DoubleArray(m+1) { Double.POSITIVE_INFINITY } }; d[0][0]=0.0; for(i in 0..n) for(j in 0..m) { if(i>0 && j>0) d[i][j]=min(d[i][j],d[i-1][j-1]+cost(i-1,j-1)); if(i>0) d[i][j]=min(d[i][j],d[i-1][j]+skip(i-1)); if(j>0) d[i][j]=min(d[i][j],d[i][j-1]+1e9) }
        val out=ArrayDeque<Pair<Slot?,Int?>>(); var i=n; var j=m; while(i>0 || j>0) when { i>0 && j>0 && d[i][j]==d[i-1][j-1]+cost(i-1,j-1) -> out.addFirst(slots[--i] to --j); i>0 && d[i][j]==d[i-1][j]+skip(i-1) -> out.addFirst(slots[--i] to null); else -> out.addFirst(null to --j) }; return out }
    fun retarget(target: ShapeTarget,profile: MotionProfileId) {
        clock.checkMutation(); val (next,charts)=admit(target); joined(next); val data=clock.spec.motion[MotionProfile.valueOf(profile.name)] as? MotionProfileSpec?:throw IllegalArgumentException("Shape intents require a scalar profile"); val access=requireNotNull(clock.context) { "Publish real EngineContext through U11.00 before a shape intent" }.access; val stamp=clock.stampNow; require(stamp.nanos>=lastStamp.nanos) { "Stale shape intent" }; purge(); val identity=listOf(next,profile,data,access); if(identity==last) return
        val sigma=if(access==MotionAccess.Faster) 2.0/3 else 1.0; val init=!presented; val now=valuesAt(stamp); val pairs=correspond(charts,next.keys,now).filter { !init || it.second!=null }; val solid=slots.indices.filter { now[4+12*it]>0 && now[5+12*it]>0 }
