            val p=centre(goal,0); val a=solid.map { nearestEdge(p,now,2+12*it) }.minByOrNull { (it-p).getDistance() }?:p; val start=if(s!=null) DoubleArray(12) { s.channels[it].rawValue(stamp) } else (if(init) goal else floatArrayOf(a.x,a.y,0f,0f)+goal.copyOfRange(4,12)).map { it.toDouble() }.toDoubleArray()
            Triple(start,DoubleArray(12) { val v=s?.channels?.get(it)?.rawVelocity(stamp)?:0.0; val b=chartBounds[it]; if(b!=null && (start[it]>=b.endInclusive && v>0 || start[it]<=b.start && v<0)) 0.0 else v },goal) } // As in prepareDrive, outward velocity at a chart bound is rounding noise at an analytic extremum.
        val plan=if(init || access==MotionAccess.Reduced) null else boundedPlan(stamp,data.easing,data.durationMs*sigma/1000,sigma,rows.flatMap { (x,v,q) -> (2..11).map { doubleArrayOf(x[it],v[it],q[it].toDouble(),chartBounds[it]!!.start,chartBounds[it]!!.endInclusive) } })
        val segment={ x: Double,v: Double,q: Float,b: ClosedFloatingPointRange<Double>? -> if(plan==null || x==q.toDouble() && v==0.0) Rest(q.toDouble()) else plan.segment(x,v,q.toDouble(),b) }; val goals=listOf(floatArrayOf(next.strain.strain,next.strain.depth))+rows.map { it.third }; val segments=listOf(strain.mapIndexed { i,m -> segment(m.rawValue(stamp),m.rawVelocity(stamp),goals[0][i],null) })+rows.map { (x,v,q) -> List(12) { segment(x[it],v[it],q[it],chartBounds[it]) } }
        val built=pairs.mapIndexed { k,(s,j) -> (s?:slot(FloatArray(12) { rows[k].first[it].toFloat() },null,stamp)).also { it.live=j!=null; if(j!=null) it.key=next.keys?.get(j) } }; val policy=if(access==MotionAccess.Reduced) "Reduced" else if(init) "Initial" else "Continuous"
        commitAtomic((listOf(strain)+built.map { it.channels }).flatMapIndexed { k,ms -> ms.mapIndexed { i,m -> m to m.prepareSegment(segments[k][i],goals[k][i],stamp,plan,policy) } }); slots.filter { it !in built }.forEach { s -> s.channels.forEach { it.dispose() } }; slots=built; this.target=next; last=identity; lastIntentWasRetarget=true; changed(stamp) }
    /** D18: C0 contact geometry; a finger cannot create or kill bodies, so the count and keys must match the current target. */ fun drive(target: ShapeTarget,stamp: FrameStamp) {
        clock.checkMutation(); val (next,charts)=admit(target); joined(next); require(charts.size==this.target.bodies.size && next.keys==this.target.keys && stamp.nanos>=lastStamp.nanos) { "A drive keeps the current bodies and moves forward in time" }; purge()
        val goals=listOf(floatArrayOf(next.strain.strain,next.strain.depth))+charts; commitAtomic((listOf(strain)+slots.filter { it.live }.map { it.channels }).zip(goals).flatMap { (ms,g) -> ms.mapIndexed { i,m -> m to m.prepareDrive(g[i],stamp) } },true); this.target=next; last=null; lastIntentWasRetarget=false; changed(stamp) }
    /** D14 side channel: replaces the join data and republishes the frame (no channel motion). */ internal fun joinPolicyData(data: JoinData) { clock.checkMutation(); require(data.gap.isFinite() && data.gap>0f) { "JoinData needs a finite positive gap" }; join=data.copy(rest=data.rest.toList()); changed(lastStamp) }
    internal fun dispose() { flat.forEach { it.dispose() } } }
@Composable fun rememberPersistentShape(key: Any): PersistentShape { val clock=ownerClock(); val shape=remember(clock,key) { PersistentShape(clock,ShapeTarget(emptyList()),key) }; DisposableEffect(shape) { onDispose { shape.dispose() } }; return shape }
